import java.io.*
import java.util.*

const val MOD = 998244353L

fun power(a: Long, e: Long): Long {
    var base = a % MOD
    if (base < 0) base += MOD
    var exp = e
    var res = 1L
    while (exp > 0) {
        if (exp and 1L == 1L) res = res * base % MOD
        base = base * base % MOD
        exp = exp shr 1
    }
    return res
}

fun main() {
    val st = StringTokenizer(BufferedReader(InputStreamReader(System.`in`)).readLine())
    val n = st.nextToken().toInt()
    val k = st.nextToken().toInt()
    val l = st.nextToken().toLong()

    val maxN = 2 * n + 5
    val fact = LongArray(maxN)
    val invFact = LongArray(maxN)
    fact[0] = 1
    for (i in 1 until maxN) fact[i] = fact[i - 1] * i % MOD
    invFact[maxN - 1] = power(fact[maxN - 1], MOD - 2)
    for (i in maxN - 1 downTo 1) invFact[i - 1] = invFact[i] * i % MOD

    fun comb(a: Int, b: Int): Long {
        if (b < 0 || b > a) return 0L
        return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD
    }

    // B[m] = (m!)^2 / (2m+1)!
    val B = LongArray(n + 1)
    for (m in 0..n) {
        B[m] = fact[m] * fact[m] % MOD * invFact[2 * m + 1] % MOD
    }
    val pow2 = LongArray(n + 1)
    pow2[0] = 1
    for (i in 1..n) pow2[i] = pow2[i - 1] * 2 % MOD

    var ans = 0L
    for (i in k..n) {
        val c = comb(n, i)
        if (c == 0L) continue
        val rem = n - i
        for (j in 0..rem) {
            val m = i + j
            var term = c * comb(rem, j) % MOD
            term = term * pow2[m] % MOD
            term = term * B[m] % MOD
            if (j and 1 == 1) {
                ans -= term
                if (ans < 0) ans += MOD
            } else {
                ans += term
                if (ans >= MOD) ans -= MOD
            }
        }
    }

    ans = ans * (l % MOD) % MOD
    println(ans)
}
